mapper.select:
SELECT id, conversation_id, sender_id, sender_type, content, 
       message_type, extra_info, send_time, is_read, is_deleted
FROM conversation_message WHERE id = #{id}

mapper.update:
UPDATE conversation_message
content = #{content}, message_type = #{messageType}, extra_info = #{extraInfo}, is_read = #{isRead}, is_deleted = #{isDeleted},
WHERE id = #{id}

UPDATE conversation_message 
SET is_read = 1
WHERE conversation_id = #{conversationId} 
AND sender_type = #{senderType}
AND is_read = 0
AND is_deleted = 0
